{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Colistin, a cyclic peptide with multiple polar/ionizable groups, has low and virtually negligible oral bioavailability, supporting low F for the query's cyclic peptide-like polar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Octreotide, a cyclic peptide, has absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers, supporting low F for cyclic peptide/polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Polymyxin B is not used orally due to poor bioavailability, supporting low F for cyclic peptide antibiotics with multiple polar groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Microcystin-LR, a cyclic peptide with multiple carboxylate groups, has low oral bioavailability in humans, supporting low F for the query's multiple carboxylate/peptide structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Acamprosate, a small zwitterionic amide-sulfonate, has absolute oral bioavailability of 11 ± 1%, supporting low F for highly polar ionizable molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Monomethyl fumarate has high oral bioavailability (90-95%), but as a small lipophilic ester it is not transferable to the query's dicarboxylate cyclic peptide; this is weak contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "L-arginine can have high oral bioavailability (~68%) via amino acid transporters, but the query lacks such a transporter-recognized amino acid motif; weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar, ionized cyclic dipeptide with two free carboxylates and multiple H-bond donors/acceptors. Experimental analogs with cyclic peptide/polar ionizable scaffolds (colistin, octreotide, polymyxin B, microcystin-LR, acamprosate) consistently show low oral bioavailability (<20%), while high-F analogs depend on active transport or small lipophilic esters not applicable here. Therefore predict low oral bioavailability at the F≥20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule",
    "No permeability or transporter data for the diketopiperazine/fumaramide scaffold",
    "Uncertainty whether the cyclic dipeptide scaffold could improve permeability relative to larger cyclic peptides",
    "No formulation or prodrug data"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

